#include <stdlib.h>
#include <string.h>

#if defined(__AVX512F__)
#define VL 16
#define MR 12
#define MC (MR * 4)
#else
#define VL 8
#define MR 6
#define MC (MR * 8)
#endif
#define NR (2 * VL)
#define NCB 128

typedef float vf __attribute__((vector_size(VL * 4), aligned(VL * 4)));
typedef float vfu __attribute__((vector_size(VL * 4), aligned(4)));

static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc)
{
    vf acc[MR][2];
#pragma GCC unroll 16
    for (int i = 0; i < MR; i++) {
        acc[i][0] = (vf){0};
        acc[i][1] = (vf){0};
    }
    int k = 0;
    for (; k + 4 <= kc; k += 4) {
#pragma GCC unroll 4
        for (int u = 0; u < 4; u++) {
            vf b0 = *(const vf *)(b + u * NR);
            vf b1 = *(const vf *)(b + u * NR + VL);
#pragma GCC unroll 16
            for (int i = 0; i < MR; i++) {
                float ai = a[u * MR + i];
                acc[i][0] += ai * b0;
                acc[i][1] += ai * b1;
            }
        }
        a += 4 * MR;
        b += 4 * NR;
    }
    for (; k < kc; k++) {
        vf b0 = *(const vf *)(b);
        vf b1 = *(const vf *)(b + VL);
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            float ai = a[i];
            acc[i][0] += ai * b0;
            acc[i][1] += ai * b1;
        }
        a += MR;
        b += NR;
    }
#pragma GCC unroll 16
    for (int i = 0; i < MR; i++) {
        *(vfu *)(c + i * ldc) = acc[i][0];
        *(vfu *)(c + i * ldc + VL) = acc[i][1];
    }
}

/* Pack MR rows of A (full K) into MR-interleaved layout, reading rows contiguously. */
static void pack_a_panel(const float *A, int n, int i0, int mr, float *ap)
{
    int i;
    for (i = 0; i < mr; i++) {
        const float *src = A + (size_t)(i0 + i) * n;
        for (int k = 0; k < n; k++)
            ap[(size_t)k * MR + i] = src[k];
    }
    for (; i < MR; i++)
        for (int k = 0; k < n; k++)
            ap[(size_t)k * MR + i] = 0.0f;
}

/* Scatter row k of B into all NR-wide panels (full K per panel). */
static void pack_b_row(const float *B, int n, int k, int npanB, float *bp)
{
    const float *src = B + (size_t)k * n;
    int nfull = n / NR;
    for (int q = 0; q < nfull; q++)
        memcpy(bp + (size_t)q * n * NR + (size_t)k * NR, src + q * NR, NR * sizeof(float));
    if (nfull < npanB) {
        float *dst = bp + (size_t)nfull * n * NR + (size_t)k * NR;
        int rem = n - nfull * NR;
        int j;
        for (j = 0; j < rem; j++) dst[j] = src[nfull * NR + j];
        for (; j < NR; j++) dst[j] = 0.0f;
    }
}

static float *g_ap = NULL, *g_bp = NULL;
static size_t g_asz = 0, g_bsz = 0;

static float *grow(float *p, size_t *cap, size_t need)
{
    if (need <= *cap) return p;
    free(p);
    need = (need + 4095) / 4096 * 4096;
    p = (float *)aligned_alloc(4096, need);
    *cap = need;
    return p;
}

void matmul(const float *A, const float *B, float *C, int n)
{
    int npanA = (n + MR - 1) / MR;
    int npanB = (n + NR - 1) / NR;
    g_ap = grow(g_ap, &g_asz, (size_t)npanA * MR * n * sizeof(float));
    g_bp = grow(g_bp, &g_bsz, (size_t)npanB * NR * n * sizeof(float));
    float *ap = g_ap, *bp = g_bp;

    int nib = (n + MC - 1) / MC;
    int njb = (n + NCB - 1) / NCB;
    int ntask = nib * njb;

#pragma omp parallel
    {
        float tile[MR * NR] __attribute__((aligned(64)));

#pragma omp for schedule(static) nowait
        for (int q = 0; q < npanA; q++) {
            int i0 = q * MR;
            int mr = n - i0 < MR ? n - i0 : MR;
            pack_a_panel(A, n, i0, mr, ap + (size_t)q * n * MR);
        }
#pragma omp for schedule(static)
        for (int k = 0; k < n; k++)
            pack_b_row(B, n, k, npanB, bp);

#pragma omp for schedule(dynamic, 1)
        for (int t = 0; t < ntask; t++) {
            int jb = t / nib, ib = t % nib;
            int i0 = ib * MC;
            int mc = n - i0 < MC ? n - i0 : MC;
            int jstart = jb * NCB;
            int jend = jstart + NCB < n ? jstart + NCB : n;
            for (int j = jstart; j < jend; j += NR) {
                int nr = n - j < NR ? n - j : NR;
                const float *bpan = bp + (size_t)(j / NR) * n * NR;
                for (int i = 0; i < mc; i += MR) {
                    int mr = mc - i < MR ? mc - i : MR;
                    const float *apan = ap + (size_t)((i0 + i) / MR) * n * MR;
                    float *cp = C + (size_t)(i0 + i) * n + j;
                    if (mr == MR && nr == NR) {
                        kernel(n, apan, bpan, cp, n);
                    } else {
                        kernel(n, apan, bpan, tile, NR);
                        for (int ii = 0; ii < mr; ii++)
                            memcpy(cp + (size_t)ii * n, tile + ii * NR, nr * sizeof(float));
                    }
                }
            }
        }
    }
}
